  areaId:"area-mps", especialidadeId:"esp-epidemio", assuntoId:"ass-bioestatistica",
  enunciado:"A medida que dimensiona se um tratamento, serviço, procedimento, programa ou outra intervenção de saúde específica produz um benefício esperado, denomina-se",
